(function managementV58(){
  const mgmt={tab:'interviews',page:1,selectedInterviews:new Set(),selectedStudies:new Set(),currentDetailId:null,deleteIds:[],audit:[],auditLoaded:false,editingSurveyId:null,previousActiveStudyId:null};
  state.auditLogs=state.auditLogs||[];
  ['owner','admin','analyst','field'].forEach(r=>ROLE_VIEWS[r]?.add('management'));

  const upper=()=>['owner','admin','analyst'].includes(currentRole());
  const allDestinationStudies=()=>state.studies.filter(s=>s.destination_id===state.destinationId);
  const memberName=id=>state.members.find(m=>m.user_id===id)?.full_name||state.members.find(m=>m.user_id===id)?.email||'—';
  const studyName=id=>state.studies.find(s=>s.id===id)?.name||'Estudio eliminado';
  const dateTime=v=>v?new Date(v).toLocaleString('es-AR',{dateStyle:'short',timeStyle:'short'}):'—';
  const safeFile=s=>String(s||'datos').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'-').replace(/^-|-$/g,'').toLowerCase();
  const downloadBlob=(blob,name)=>{const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1500)};
  const jsonClone=o=>JSON.parse(JSON.stringify(o??null));

  const baseSwitchView=switchView;
  switchView=function(view){baseSwitchView(view);if(view==='management')renderManagement()};

  const basePrepareSurveyV58=prepareSurvey;
  prepareSurvey=function(){
    if(!mgmt.editingSurveyId&&activeStudy()?.status==='archived'){const usable=allDestinationStudies().find(s=>s.status!=='archived');if(usable){state.activeStudyId=usable.id;populateSelectors();toast('El estudio seleccionado está archivado. La entrevista se cargará en el estudio activo.','warning')}else{toast('No hay un estudio activo para registrar entrevistas. Reactivá o creá uno.','warning')}}
    return basePrepareSurveyV58();
  };

  const baseApplyRoleAccess=applyRoleAccess;
  applyRoleAccess=function(){baseApplyRoleAccess();const isField=currentRole()==='field';const nav=$('managementNavBtn');if(nav){const title=nav.querySelector('b'),sub=nav.querySelector('small');if(title)title.textContent=isField?'Mis entrevistas':'Gestión de datos';if(sub)sub.textContent=isField?'Revisar y corregir':'Entrevistas e historial';}qsa('[data-mgmt-admin]').forEach(x=>x.classList.toggle('d-none',isField));qsa('[data-upper-only]').forEach(x=>x.classList.toggle('d-none',isField));$('managementTitle')&&($('managementTitle').textContent=isField?'Mis entrevistas':'Gestión de datos');$('managementSubtitle')&&($('managementSubtitle').textContent=isField?'Revisá las entrevistas que cargaste y corregí cualquier error dejando un motivo.':'Revisá entrevistas, administrá estudios, consultá el historial y descargá respaldos.')};

  const basePopulateSelectorsV58=populateSelectors;
  populateSelectors=function(){
    const activeNow=state.studies.find(s=>s.id===state.activeStudyId);
    if(activeNow?.status==='archived'){
      const replacement=allDestinationStudies().find(s=>s.status!=='archived');
      if(replacement)state.activeStudyId=replacement.id;
    }
    basePopulateSelectorsV58();
    const activeSel=$('activeStudySelect');
    if(activeSel){
      [...activeSel.options].forEach(o=>{const st=state.studies.find(s=>s.id===o.value);if(st?.status==='archived'){o.disabled=true;o.textContent=`${st.name} · archivado`;}});
    }
  };

  // ---------- Auditoría ----------
  async function recordAudit({entityType,entityId=null,action,reason=null,before=null,after=null,studyId=null,metadata={}}){
    const log={id:uid(),organization_id:state.org?.id,destination_id:state.destinationId,study_id:studyId,actor_user_id:state.user?.id,actor_email:state.user?.email,entity_type:entityType,entity_id:entityId,action,reason,before_data:before,after_data:after,metadata,created_at:new Date().toISOString()};
    if(state.mode==='demo'){state.auditLogs.unshift(log);mgmt.audit.unshift(log);return log.id}
    const {data,error}=await sb.rpc('record_audit_event',{p_organization_id:state.org.id,p_destination_id:state.destinationId,p_study_id:studyId,p_entity_type:entityType,p_entity_id:entityId,p_action:action,p_reason:reason,p_before_data:before,p_after_data:after,p_metadata:metadata});
    if(error)console.warn('No se pudo registrar auditoría:',error.message);else mgmt.auditLoaded=false;
    return data;
  }
  async function loadAudit(force=false){
    if(currentRole()==='field')return [];
    if(state.mode==='demo'){mgmt.audit=state.auditLogs||[];mgmt.auditLoaded=true;return mgmt.audit}
    if(mgmt.auditLoaded&&!force)return mgmt.audit;
    const {data,error}=await sb.from('audit_logs').select('*').eq('organization_id',state.org.id).order('created_at',{ascending:false}).limit(1500);
    if(error){toast(`No se pudo cargar el historial: ${error.message}`,'danger');return []}
    mgmt.audit=data||[];mgmt.auditLoaded=true;return mgmt.audit;
  }

  async function refreshManagementData(){
    if(state.mode==='demo')return;
    const orgId=state.org?.id;if(!orgId)return;
    try{
      const fetchPaged=async(table,orderCol=null)=>{const out=[];for(let from=0;;from+=1000){let q=sb.from(table).select('*').eq('organization_id',orgId).range(from,from+999);if(orderCol)q=q.order(orderCol,{ascending:false});const {data,error}=await q;if(error)throw error;out.push(...(data||[]));if(!data||data.length<1000)break}return out};
      const [studies,questions,interviews,events,coverage]=await Promise.all([fetchPaged('studies'),fetchPaged('survey_questions'),fetchPaged('visitor_records','visited_at'),fetchPaged('field_events','event_at'),fetchPaged('coverage_targets')]);
      state.studies=studies;state.questions=questions;state.surveys=interviews;state.events=events;state.coverage=coverage;
      const current=state.studies.find(s=>s.id===state.activeStudyId);if(!current||current.status==='archived')state.activeStudyId=allDestinationStudies().find(s=>s.status!=='archived')?.id||allDestinationStudies()[0]?.id||null;
      populateSelectors();mgmt.auditLoaded=false;
    }catch(err){toast(`No se pudo actualizar la gestión: ${err.message||err}`,'danger')}
  }

  // ---------- Gestión view ----------
  function showMgmtTab(tab){
    if(currentRole()==='field')tab='interviews';mgmt.tab=tab;
    qsa('[data-mgmt-tab]').forEach(b=>b.classList.toggle('active',b.dataset.mgmtTab===tab));
    qsa('[data-mgmt-pane]').forEach(p=>p.classList.toggle('d-none',p.dataset.mgmtPane!==tab));
    if(tab==='interviews')renderInterviewManager();
    if(tab==='studies')renderStudyManager();
    if(tab==='audit')renderAudit();
  }
  function renderManagement(){
    applyRoleAccess();
    populateManagementStudyFilter();
    showMgmtTab(mgmt.tab);
  }
  function populateManagementStudyFilter(){
    const sel=$('mgmtInterviewStudy');if(!sel)return;const keep=sel.value;
    sel.innerHTML=`<option value="">Todos los estudios</option>${allDestinationStudies().map(s=>`<option value="${s.id}">${esc(s.name)}${s.status==='archived'?' · archivado':''}</option>`).join('')}`;
    if([...sel.options].some(o=>o.value===keep))sel.value=keep;
  }

  // ---------- Entrevistas ----------
  function interviewFilterRows(){
    let rows=state.surveys.filter(r=>r.destination_id===state.destinationId);
    if(currentRole()==='field')rows=rows.filter(r=>r.created_by===state.user.id);
    const study=$('mgmtInterviewStudy')?.value||'';if(study)rows=rows.filter(r=>r.study_id===study);
    const term=($('mgmtInterviewSearch')?.value||'').trim().toLowerCase();
    if(term)rows=rows.filter(r=>[r.field_point,r.origin_country,r.origin_province,r.origin_city,r.trip_purpose,memberName(r.created_by),studyName(r.study_id)].some(v=>String(v||'').toLowerCase().includes(term)));
    return rows.sort((a,b)=>new Date(b.visited_at)-new Date(a.visited_at));
  }
  function renderInterviewManager(){
    const rows=interviewFilterRows(),limit=Number($('mgmtInterviewLimit')?.value||50),pages=Math.max(1,Math.ceil(rows.length/limit));if(mgmt.page>pages)mgmt.page=pages;
    const pageRows=rows.slice((mgmt.page-1)*limit,mgmt.page*limit);
    $('mgmtInterviewRows').innerHTML=pageRows.map(r=>`<tr>
      <td>${upper()?`<input class="form-check-input mgmt-interview-check" type="checkbox" value="${r.id}" ${mgmt.selectedInterviews.has(r.id)?'checked':''}>`:''}</td>
      <td>${dateTime(r.visited_at)}</td><td>${esc(memberName(r.created_by))}</td><td>${esc(studyName(r.study_id))}</td><td>${esc(r.field_point||'—')}</td>
      <td>${esc([r.origin_city,r.origin_province,r.origin_country].filter(Boolean).join(' · ')||'—')}</td><td>${r.updated_at?`${dateTime(r.updated_at)}<br><small>${esc(memberName(r.updated_by))}</small>`:'—'}</td>
      <td><div class="d-flex gap-1 flex-wrap"><button class="btn btn-outline-secondary btn-sm" data-interview-action="view" data-id="${r.id}">Ver</button><button class="btn btn-outline-secondary btn-sm" data-interview-action="edit" data-id="${r.id}">Editar</button></div></td>
    </tr>`).join('')||`<tr><td colspan="8" class="text-secondary">No hay entrevistas con estos filtros.</td></tr>`;
    $('mgmtPageInfo').textContent=`Página ${mgmt.page} de ${pages} · ${fmt(rows.length)} entrevistas`;$('mgmtPrevPage').disabled=mgmt.page<=1;$('mgmtNextPage').disabled=mgmt.page>=pages;
    updateInterviewSelectionLabel();
    const visibleIds=pageRows.map(r=>r.id);$('mgmtInterviewSelectAll').checked=visibleIds.length>0&&visibleIds.every(id=>mgmt.selectedInterviews.has(id));
  }
  function selectedInterviewRows(){return state.surveys.filter(r=>mgmt.selectedInterviews.has(r.id))}
  function updateInterviewSelectionLabel(){$('mgmtInterviewSelection')&&($('mgmtInterviewSelection').textContent=`${mgmt.selectedInterviews.size} seleccionada${mgmt.selectedInterviews.size===1?'':'s'}`)}
  function toggleVisibleInterviewSelection(checked){const rows=interviewFilterRows(),limit=Number($('mgmtInterviewLimit')?.value||50),pageRows=rows.slice((mgmt.page-1)*limit,mgmt.page*limit);pageRows.forEach(r=>checked?mgmt.selectedInterviews.add(r.id):mgmt.selectedInterviews.delete(r.id));renderInterviewManager()}
  function selectAllInterviewResults(){interviewFilterRows().forEach(r=>mgmt.selectedInterviews.add(r.id));renderInterviewManager();toast(`${mgmt.selectedInterviews.size} entrevistas seleccionadas.`)}

  function interviewDetailHtml(r){
    const value=v=>Array.isArray(v)?v.join(' · '):(v===true?'Sí':v===false?'No':(v??'—'));
    const rows=(pairs)=>pairs.map(([k,v])=>`<div class="detail-row"><span>${esc(k)}</span><b>${esc(value(v))}</b></div>`).join('');
    const custom=allStudyQuestions(r.study_id).map(q=>[q.text,r.survey_answers?.[q.id]]).filter(x=>x[1]!==undefined&&x[1]!==null&&x[1]!=='');
    return `<div class="interview-detail-grid">
      <section class="interview-detail-section"><h4>Registro</h4>${rows([['Fecha',dateTime(r.visited_at)],['Estudio',studyName(r.study_id)],['Encuestador',memberName(r.created_by)],['Punto',r.field_point],['Franja',labelMap[r.time_band]||r.time_band],['GPS',r.latitude!=null?`${r.latitude}, ${r.longitude} · ${r.gps_accuracy_m||'—'} m`:'No']])}</section>
      <section class="interview-detail-section"><h4>Perfil</h4>${rows([['Origen',[r.origin_city,r.origin_province,r.origin_country].filter(Boolean).join(' · ')],['Residencia',r.residence_area],['Edad',r.age_range],['Grupo',r.party_type],['Personas',r.party_size],['Primera visita',r.first_visit]])}</section>
      <section class="interview-detail-section"><h4>Viaje</h4>${rows([['Motivo',r.trip_purpose],['Pernocta',r.overnight],['Noches',r.nights],['Alojamiento',r.accommodation],['Transporte',labelMap[r.transport_mode]||r.transport_mode],['Reserva',labelMap[r.booking_channel]||r.booking_channel],['Motivaciones',r.motivations],['Actividades',r.activities],['Lugares',r.neighborhoods]])}</section>
      <section class="interview-detail-section"><h4>Experiencia</h4>${rows([['Recomendaría',r.recommend_score],['Volvería',r.revisit_score],['Experiencia general',r.overall_satisfaction],['Problemas',r.problems],['Problema principal',r.main_problem],['Necesidad no resuelta',r.has_unmet_need],['Qué necesitó',r.unmet_need_text]])}</section>
      <section class="interview-detail-section full"><h4>Gasto por persona/día</h4>${rows([['Moneda',r.spend_currency],...SPEND_KEYS.map(k=>[SPEND_LABELS[k],r[k]])])}</section>
      ${custom.length?`<section class="interview-detail-section full"><h4>Preguntas adicionales</h4>${rows(custom)}</section>`:''}
      ${r.field_observation?`<section class="interview-detail-section full"><h4>Observación</h4><p>${esc(r.field_observation)}</p></section>`:''}
      ${r.updated_at?`<section class="interview-detail-section full"><h4>Última corrección</h4>${rows([['Fecha',dateTime(r.updated_at)],['Usuario',memberName(r.updated_by)],['Motivo',r.last_edit_reason]])}</section>`:''}
    </div>`;
  }
  function openInterviewDetail(id){const r=state.surveys.find(x=>x.id===id);if(!r)return;mgmt.currentDetailId=id;$('interviewDetailTitle').textContent=`Entrevista · ${dateTime(r.visited_at)}`;$('interviewDetailBody').innerHTML=interviewDetailHtml(r);bootstrap.Modal.getOrCreateInstance($('interviewDetailModal')).show()}

  function setInput(id,v){const el=$(id);if(!el)return;el.value=v??''}
  function setCheckboxGroup(name,values){const set=new Set(arr(values).map(String));qsa(`input[name="${name}"]`).forEach(x=>x.checked=set.has(String(x.value)))}
  function fillInterviewForm(r){
    setInput('surveyPoint',r.field_point);setInput('surveyTimeBand',r.time_band);setInput('surveySelection',r.selection_method);setInput('originCountry',r.origin_country);setInput('originProvince',r.origin_province);setInput('originCity',r.origin_city);setInput('residenceArea',r.residence_area);setInput('usualCommuter',String(!!r.usual_commuter));setInput('ageRange',r.age_range);setInput('gender',r.gender);setInput('partyType',r.party_type);setInput('partySize',r.party_size);setInput('childrenCount',r.children_count);setInput('tripPurpose',r.trip_purpose);setInput('firstVisit',String(!!r.first_visit));setInput('previousVisits',r.previous_visits);setInput('overnight',String(!!r.overnight));setInput('nights',r.nights);setInput('accommodation',r.accommodation);setCheckboxGroup('motivations',r.motivations);setInput('primaryDriver',r.primary_driver);setInput('alternativeDestination',r.alternative_destination);setInput('planningLead',r.planning_lead);setInput('transportMode',r.transport_mode);setCheckboxGroup('channels',r.info_channels);setInput('primaryInfoChannel',r.primary_info_channel);setInput('bookingChannel',r.booking_channel);setCheckboxGroup('activities',r.activities);setInput('primaryActivity',r.primary_activity);setCheckboxGroup('neighborhoods',r.neighborhoods);setInput('mainNeighborhood',r.main_neighborhood);setInput('missedNeighborhood',r.missed_neighborhood);setInput('missedNeighborhoodReason',r.missed_neighborhood_reason);setInput('spendCurrency',r.spend_currency);setInput('spendAccommodation',r.spend_accommodation);setInput('spendFood',r.spend_food);setInput('spendTransport',r.spend_transport);setInput('spendActivities',r.spend_activities);setInput('spendCulture',r.spend_culture);setInput('spendShopping',r.spend_shopping);setInput('spendOther',r.spend_other);setCheckboxGroup('importance',r.importance_factors);qsa('.sat-input').forEach(x=>x.value=r.satisfaction?.[x.dataset.attribute]??'');setInput('recommendScore',r.recommend_score);setInput('revisitScore',r.revisit_score);setInput('overallSatisfaction',r.overall_satisfaction);setInput('preferredSeason',r.preferred_season);setCheckboxGroup('problems',r.problems);setInput('mainProblem',r.main_problem);setInput('problemSeverity',r.problem_severity);setInput('blockedAction',String(!!r.blocked_action));setInput('lostPurchase',String(!!r.lost_purchase));setInput('hasUnmetNeed',String(!!r.has_unmet_need));setInput('unmetCategory',r.unmet_category);setInput('unmetNeedText',r.unmet_need_text);setInput('unmetReason',r.unmet_reason);setInput('unmetImportance',r.unmet_importance);setInput('wouldPay',r.would_pay);setInput('expectedSolution',r.expected_solution);setInput('expectedPrice',r.expected_price);setInput('expectedPriceCurrency',r.expected_price_currency);setInput('couldExtendStay',String(!!r.could_extend_stay));setInput('stayExtensionDriver',r.stay_extension_driver);setInput('conceptName',r.concept_name);setInput('conceptInterest',r.concept_interest);setInput('conceptPurchase',r.concept_purchase);setInput('fieldObservation',r.field_observation);toggleUnmet();updateEligibility();syncBookingChannel();
    qsa('.custom-answer').forEach(el=>{const qid=el.dataset.q,v=r.survey_answers?.[qid];if(el.type==='checkbox')el.checked=arr(v).map(String).includes(String(el.value));else el.value=v??''});
    state.gps=r.latitude!=null?{latitude:r.latitude,longitude:r.longitude,gps_accuracy_m:r.gps_accuracy_m}:null;$('gpsStatus').textContent=r.latitude!=null?`Ubicación guardada · precisión ${fmt(r.gps_accuracy_m,0)} m`:'Sin ubicación.';
  }
  // En modo corrección, el guardado debe estar siempre disponible.
  // La navegación base puede ocultar el botón hasta el último paso; para una
  // corrección eso resulta confuso y puede impedir guardar cambios válidos.
  const baseUpdateSurveyNavigationV58=updateSurveyNavigation;
  updateSurveyNavigation=function(){
    baseUpdateSurveyNavigationV58();
    if(mgmt.editingSurveyId&&$('surveySaveBtn')){
      $('surveySaveBtn').classList.remove('d-none');
      $('surveySaveBtn').textContent='Guardar corrección';
    }
  };

  function openInterviewEdit(id){
    const r=state.surveys.find(x=>x.id===id);if(!r)return;if(currentRole()==='field'&&r.created_by!==state.user.id)return toast('Sólo podés corregir entrevistas cargadas por vos.','warning');
    mgmt.editingSurveyId=id;mgmt.previousActiveStudyId=state.activeStudyId;state.activeStudyId=r.study_id;prepareSurvey();fillInterviewForm(r);$('surveyModeEyebrow').textContent='Corrección';$('surveyModalTitle').textContent='Editar entrevista';$('surveyEditReasonWrap').classList.remove('d-none');$('surveyEditReason').value='';$('surveySaveBtn').textContent='Guardar corrección';$('surveySaveBtn').classList.remove('d-none');bootstrap.Modal.getOrCreateInstance($('surveyModal')).show();
  }
  function collectInterviewUpdate(existing){
    const satisfaction={};qsa('.sat-input').forEach(x=>{if(x.value!=='')satisfaction[x.dataset.attribute]=Number(x.value)});
    const payload={field_point:$('surveyPoint').value.trim(),time_band:$('surveyTimeBand').value,selection_method:$('surveySelection').value,origin_country:$('originCountry').value.trim(),origin_province:$('originProvince').value.trim()||null,origin_city:$('originCity').value.trim()||null,residence_area:$('residenceArea').value,usual_commuter:bool($('usualCommuter').value),age_range:$('ageRange').value,gender:$('gender').value||null,party_type:$('partyType').value,party_size:num($('partySize').value)||1,children_count:num($('childrenCount').value)||0,trip_purpose:$('tripPurpose').value,first_visit:bool($('firstVisit').value),previous_visits:num($('previousVisits').value)||0,overnight:bool($('overnight').value),nights:num($('nights').value)||0,accommodation:$('accommodation').value,motivations:checked('motivations'),primary_driver:$('primaryDriver').value,alternative_destination:$('alternativeDestination').value.trim()||null,planning_lead:$('planningLead').value,transport_mode:$('transportMode')?.value||null,info_channels:checked('channels'),primary_info_channel:$('primaryInfoChannel')?.value||null,booking_channel:$('bookingChannel')?.value||null,activities:checked('activities'),primary_activity:$('primaryActivity')?.value||null,neighborhoods:checked('neighborhoods'),main_neighborhood:$('mainNeighborhood').value||null,missed_neighborhood:$('missedNeighborhood').value||null,missed_neighborhood_reason:$('missedNeighborhoodReason').value||null,spend_currency:$('spendCurrency').value,spend_accommodation:num($('spendAccommodation').value),spend_food:num($('spendFood').value),spend_transport:num($('spendTransport').value),spend_activities:num($('spendActivities').value),spend_culture:num($('spendCulture').value),spend_shopping:num($('spendShopping').value),spend_other:num($('spendOther').value),importance_factors:checked('importance'),satisfaction,recommend_score:num($('recommendScore').value),revisit_score:num($('revisitScore').value),overall_satisfaction:num($('overallSatisfaction').value),preferred_season:$('preferredSeason')?.value||null,problems:checked('problems'),main_problem:$('mainProblem').value||null,problem_severity:num($('problemSeverity').value),blocked_action:bool($('blockedAction').value),lost_purchase:bool($('lostPurchase').value),has_unmet_need:bool($('hasUnmetNeed').value),unmet_category:bool($('hasUnmetNeed').value)?$('unmetCategory').value:null,unmet_need_text:bool($('hasUnmetNeed').value)?$('unmetNeedText').value.trim()||null:null,unmet_reason:bool($('hasUnmetNeed').value)?$('unmetReason').value:null,unmet_importance:bool($('hasUnmetNeed').value)?num($('unmetImportance').value):null,would_pay:bool($('hasUnmetNeed').value)?$('wouldPay').value:null,expected_solution:bool($('hasUnmetNeed').value)?$('expectedSolution').value.trim()||null:null,expected_price:bool($('hasUnmetNeed').value)?num($('expectedPrice').value):null,expected_price_currency:$('expectedPriceCurrency').value,could_extend_stay:bool($('couldExtendStay').value),stay_extension_driver:bool($('couldExtendStay').value)?$('stayExtensionDriver').value:null,concept_name:$('conceptName').value.trim()||null,concept_interest:num($('conceptInterest').value),concept_purchase:num($('conceptPurchase').value),field_observation:$('fieldObservation').value.trim()||null,survey_answers:collectCustomAnswers(),latitude:state.gps?.latitude??existing.latitude??null,longitude:state.gps?.longitude??existing.longitude??null,gps_accuracy_m:state.gps?.gps_accuracy_m??existing.gps_accuracy_m??null,updated_at:new Date().toISOString(),updated_by:state.user.id,last_edit_reason:$('surveyEditReason').value.trim()};
    scrubDisabledCore(payload,state.studies.find(s=>s.id===existing.study_id));payload.visitor_type=visitorType({...existing,...payload});return payload;
  }
  async function saveInterviewCorrection(e){
    if(!mgmt.editingSurveyId)return; e.preventDefault();e.stopImmediatePropagation();if(!validateCustomRequired())return;const existing=state.surveys.find(r=>r.id===mgmt.editingSurveyId);if(!existing)return;const reason=$('surveyEditReason').value.trim();if(!reason)return toast('Escribí el motivo de la corrección.','warning');const payload=collectInterviewUpdate(existing);
    if(state.mode==='demo'){const before=jsonClone(existing);Object.assign(existing,payload);await recordAudit({entityType:'interview',entityId:existing.id,action:'update',reason,before,after:jsonClone(existing),studyId:existing.study_id});saveDemo()}else{const {data,error}=await sb.from('visitor_records').update(payload).eq('id',existing.id).select().single();if(error)return toast(`No se pudo guardar la corrección: ${error.message}`,'danger');Object.assign(existing,data)}
    bootstrap.Modal.getOrCreateInstance($('surveyModal')).hide();toast('Corrección guardada y registrada en el historial.');renderAll();renderManagement();
  }
  function resetInterviewEdit(){if(!mgmt.editingSurveyId)return;mgmt.editingSurveyId=null;$('surveyEditReasonWrap')?.classList.add('d-none');$('surveyEditReason')&&($('surveyEditReason').value='');$('surveyModeEyebrow')&&($('surveyModeEyebrow').textContent='Entrevista');$('surveyModalTitle')&&($('surveyModalTitle').textContent='Registrar visitante');$('surveySaveBtn')&&($('surveySaveBtn').textContent='Guardar entrevista');if(mgmt.previousActiveStudyId){state.activeStudyId=mgmt.previousActiveStudyId;mgmt.previousActiveStudyId=null;populateSelectors()}}

  // ---------- Exportaciones ----------
  function exportObjects(rows){
    const qByStudy=new Map();return rows.map((r,i)=>{if(!qByStudy.has(r.study_id))qByStudy.set(r.study_id,allStudyQuestions(r.study_id));const out={N:i+1,'ID entrevista':r.id,'Fecha y hora':r.visited_at,'Estudio':studyName(r.study_id),'Encuestador':memberName(r.created_by),'Punto de relevamiento':r.field_point,'Franja':labelMap[r.time_band]||r.time_band,'País':r.origin_country,'Provincia / Estado':r.origin_province,'Ciudad':r.origin_city,'Tipo de visitante':labelMap[r.visitor_type]||r.visitor_type,'Edad':r.age_range,'Grupo de viaje':r.party_type,'Cantidad de personas':r.party_size,'Motivo principal':r.trip_purpose,'Pernocta':r.overnight?'Sí':'No','Noches':r.nights,'Alojamiento':r.accommodation,'Transporte':labelMap[r.transport_mode]||r.transport_mode,'Canal principal':r.primary_info_channel,'Reserva':labelMap[r.booking_channel]||r.booking_channel,'Motivaciones':arr(r.motivations).join(' | '),'Actividades':arr(r.activities).join(' | '),'Lugares visitados':arr(r.neighborhoods).join(' | '),'Moneda gasto':r.spend_currency,'Alojamiento gasto':r.spend_accommodation,'Gastronomía gasto':r.spend_food,'Transporte gasto':r.spend_transport,'Actividades gasto':r.spend_activities,'Cultura gasto':r.spend_culture,'Compras gasto':r.spend_shopping,'Otros gasto':r.spend_other,'Recomendaría 0-10':r.recommend_score,'Volvería 0-10':r.revisit_score,'Experiencia 0-10':r.overall_satisfaction,'Problemas':arr(r.problems).join(' | '),'Necesidad no resuelta':r.has_unmet_need?'Sí':'No','Necesidad':r.unmet_need_text,'Motivo corrección':r.last_edit_reason,'Última edición':r.updated_at,'Editado por':r.updated_by?memberName(r.updated_by):''};for(const q of qByStudy.get(r.study_id)||[]){const v=r.survey_answers?.[q.id];out[q.text]=Array.isArray(v)?v.join(' | '):(v??'')}return out})
  }
  function requireExportRows(){const rows=selectedInterviewRows();if(!rows.length){toast('Seleccioná una o más entrevistas.','warning');return null}return rows}
  async function logExport(rows,format){await recordAudit({entityType:'backup',action:`export_${format}`,reason:`Exportación de ${rows.length} entrevista(s)`,studyId:rows.length&&new Set(rows.map(r=>r.study_id)).size===1?rows[0].study_id:null,metadata:{count:rows.length,format,ids:rows.map(r=>r.id)}})}
  async function exportSelectedCsv(){const rows=requireExportRows();if(!rows)return;const data=exportObjects(rows),headers=[...new Set(data.flatMap(Object.keys))],csv=[headers,...data.map(o=>headers.map(h=>o[h]??''))].map(row=>row.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(';')).join('\r\n');downloadBlob(new Blob(['\uFEFFsep=;\r\n'+csv],{type:'text/csv;charset=utf-8'}),`destintelligence-entrevistas-${new Date().toISOString().slice(0,10)}.csv`);await logExport(rows,'csv')}
  async function exportSelectedExcel(){const rows=requireExportRows();if(!rows)return;if(typeof XLSX==='undefined'){toast('No se cargó el módulo Excel. Se descargará CSV como alternativa.','warning');return exportSelectedCsv()}const data=exportObjects(rows),ws=XLSX.utils.json_to_sheet(data);ws['!cols']=Object.keys(data[0]||{}).map(h=>({wch:Math.min(45,Math.max(12,h.length+2,...data.slice(0,100).map(r=>String(r[h]??'').length+2)))}));const meta=XLSX.utils.aoa_to_sheet([['Destintelligence · Exportación de entrevistas'],['Fecha',new Date().toLocaleString('es-AR')],['Destino',activeDestination()?.name||''],['Cantidad',rows.length],['Estudios',[...new Set(rows.map(r=>studyName(r.study_id)))].join(' | ')]]),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Entrevistas');XLSX.utils.book_append_sheet(wb,meta,'Información');XLSX.writeFile(wb,`destintelligence-entrevistas-${new Date().toISOString().slice(0,10)}.xlsx`);await logExport(rows,'xlsx')}
  function printableInterviewHtml(rows){return `<!doctype html><html><head><meta charset="utf-8"><title>Destintelligence</title><style>body{font-family:Arial,sans-serif;color:#17231f;margin:28px}h1{font-size:22px}h2{font-size:16px;margin-top:24px}table{border-collapse:collapse;width:100%;font-size:10px}th,td{border:1px solid #ddd;padding:6px;text-align:left;vertical-align:top}th{background:#f2f5f3}.record{page-break-after:always}.record:last-child{page-break-after:auto}.kv{display:grid;grid-template-columns:180px 1fr;border-bottom:1px solid #eee;padding:5px 0}.muted{color:#667}</style></head><body><h1>Destintelligence · Entrevistas</h1><p class="muted">Destino: ${esc(activeDestination()?.name||'')} · ${rows.length} registro(s) · ${new Date().toLocaleString('es-AR')}</p>${rows.length<=10?rows.map(r=>`<div class="record"><h2>${dateTime(r.visited_at)} · ${esc(r.field_point||'')}</h2>${interviewDetailHtml(r)}</div>`).join(''):`<table><thead><tr><th>Fecha</th><th>Estudio</th><th>Encuestador</th><th>Punto</th><th>Origen</th><th>Motivo</th><th>Satisfacción</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${dateTime(r.visited_at)}</td><td>${esc(studyName(r.study_id))}</td><td>${esc(memberName(r.created_by))}</td><td>${esc(r.field_point||'')}</td><td>${esc([r.origin_province,r.origin_country].filter(Boolean).join(' · '))}</td><td>${esc(r.trip_purpose||'')}</td><td>${esc(r.overall_satisfaction??'—')}</td></tr>`).join('')}</tbody></table>`}</body></html>`}
  async function exportSelectedPdf(explicitRows=null){
    const rows=explicitRows||requireExportRows();if(!rows)return;
    if(!window.jspdf?.jsPDF){const w=window.open('','_blank');w.document.write(printableInterviewHtml(rows));w.document.close();setTimeout(()=>w.print(),250);await logExport(rows,'pdf');return}
    const {jsPDF}=window.jspdf;
    const single=rows.length===1;
    const doc=new jsPDF({orientation:single?'portrait':'landscape',unit:'mm',format:'a4'});
    const margin=12,pageW=doc.internal.pageSize.getWidth(),pageH=doc.internal.pageSize.getHeight();
    const header=()=>{doc.setFont('helvetica','bold');doc.setFontSize(16);doc.text('Destintelligence',margin,14);doc.setFont('helvetica','normal');doc.setFontSize(9);doc.text(`${activeDestination()?.name||''} · ${single?'Ficha de entrevista':`${rows.length} entrevistas`} · ${new Date().toLocaleString('es-AR')}`,margin,20);doc.setDrawColor(210);doc.line(margin,23,pageW-margin,23)};
    header();
    if(single){
      const r=rows[0],sections=[
        ['Registro',[['Fecha y hora',dateTime(r.visited_at)],['Estudio',studyName(r.study_id)],['Encuestador',memberName(r.created_by)],['Punto de relevamiento',r.field_point||'—'],['Franja',labelMap[r.time_band]||r.time_band||'—'],['GPS',r.latitude!=null?`${r.latitude}, ${r.longitude} · precisión ${r.gps_accuracy_m||'—'} m`:'No registrado']]],
        ['Perfil',[['Origen',[r.origin_city,r.origin_province,r.origin_country].filter(Boolean).join(' · ')||'—'],['Residencia habitual',r.residence_area||'—'],['Edad',r.age_range||'—'],['Grupo',r.party_type||'—'],['Personas',r.party_size??'—'],['Primera visita',r.first_visit===true?'Sí':r.first_visit===false?'No':'—']]],
        ['Viaje',[['Motivo principal',r.trip_purpose||'—'],['Pernocta',r.overnight?'Sí':'No'],['Noches',r.nights??'—'],['Alojamiento',r.accommodation||'—'],['Transporte',labelMap[r.transport_mode]||r.transport_mode||'—'],['Canal de reserva',labelMap[r.booking_channel]||r.booking_channel||'—'],['Motivaciones',arr(r.motivations).join(' · ')||'—'],['Actividades',arr(r.activities).join(' · ')||'—'],['Lugares visitados',arr(r.neighborhoods).join(' · ')||'—']]],
        ['Experiencia',[['Recomendaría (0–10)',r.recommend_score??'—'],['Volvería (0–10)',r.revisit_score??'—'],['Experiencia general (0–10)',r.overall_satisfaction??'—'],['Problemas',arr(r.problems).join(' · ')||'—'],['Problema principal',r.main_problem||'—'],['Necesidad no resuelta',r.has_unmet_need?'Sí':'No'],['Qué necesitó',r.unmet_need_text||'—']]],
        ['Gasto por persona/día',[['Moneda',r.spend_currency||'—'],...SPEND_KEYS.map(k=>[SPEND_LABELS[k],r[k]??'—'])]]
      ];
      let y=29;
      const ensure=(need=18)=>{if(y+need>pageH-12){doc.addPage();header();y=29}};
      for(const [title,pairs] of sections){ensure(20);doc.setFont('helvetica','bold');doc.setFontSize(11);doc.text(title,margin,y);y+=5;doc.setFont('helvetica','normal');doc.setFontSize(8.5);for(const [k,v] of pairs){const txt=`${k}: ${v??'—'}`,lines=doc.splitTextToSize(txt,pageW-margin*2);ensure(lines.length*4+2);doc.text(lines,margin,y);y+=lines.length*4+1}y+=3}
      const custom=allStudyQuestions(r.study_id).map(q=>[q.text,r.survey_answers?.[q.id]]).filter(([,v])=>v!==undefined&&v!==null&&v!=='');
      if(custom.length){ensure(18);doc.setFont('helvetica','bold');doc.setFontSize(11);doc.text('Preguntas adicionales',margin,y);y+=5;doc.setFont('helvetica','normal');doc.setFontSize(8.5);for(const [q,v] of custom){const val=Array.isArray(v)?v.join(' · '):v,lines=doc.splitTextToSize(`${q}: ${val}`,pageW-margin*2);ensure(lines.length*4+2);doc.text(lines,margin,y);y+=lines.length*4+1}}
      if(r.field_observation){ensure(18);doc.setFont('helvetica','bold');doc.setFontSize(11);doc.text('Observación del encuestador',margin,y);y+=5;doc.setFont('helvetica','normal');doc.setFontSize(8.5);const lines=doc.splitTextToSize(r.field_observation,pageW-margin*2);doc.text(lines,margin,y);y+=lines.length*4}
      if(r.updated_at){ensure(18);y+=4;doc.setFont('helvetica','bold');doc.setFontSize(10);doc.text('Última corrección',margin,y);y+=5;doc.setFont('helvetica','normal');doc.setFontSize(8.5);const lines=doc.splitTextToSize(`${dateTime(r.updated_at)} · ${memberName(r.updated_by)} · Motivo: ${r.last_edit_reason||'—'}`,pageW-margin*2);doc.text(lines,margin,y)}
    }else if(typeof doc.autoTable==='function'){
      const body=rows.map(r=>[dateTime(r.visited_at),studyName(r.study_id),memberName(r.created_by),r.field_point||'—',[r.origin_province,r.origin_country].filter(Boolean).join(' · ')||'—',r.trip_purpose||'—',r.overnight?'Sí':'No',r.nights??'—',r.recommend_score??'—',r.overall_satisfaction??'—']);
      doc.autoTable({startY:28,head:[['Fecha','Estudio','Encuestador','Punto','Origen','Motivo','Pernocta','Noches','NPS','Satisf.']],body,styles:{fontSize:7,cellPadding:1.7,overflow:'linebreak'},headStyles:{fillColor:[49,93,77]},margin:{left:margin,right:margin,bottom:12},didDrawPage:()=>{if(doc.internal.getNumberOfPages()>1)header()}});
    }else{
      let y=30;doc.setFontSize(8);for(let i=0;i<rows.length;i++){const r=rows[i];if(y>pageH-16){doc.addPage();header();y=29}const line=`${i+1}. ${dateTime(r.visited_at)} | ${studyName(r.study_id)} | ${memberName(r.created_by)} | ${r.field_point||''} | ${r.trip_purpose||''}`;const wrapped=doc.splitTextToSize(line,pageW-margin*2);doc.text(wrapped,margin,y);y+=wrapped.length*4+2}}
    const pages=doc.internal.getNumberOfPages();for(let i=1;i<=pages;i++){doc.setPage(i);doc.setFontSize(7);doc.setTextColor(110);doc.text(`Página ${i} de ${pages}`,pageW-margin-18,pageH-6)}
    doc.save(`destintelligence-entrevistas-${new Date().toISOString().slice(0,10)}.pdf`);await logExport(rows,'pdf')
  }

  // ---------- Estudios ----------
  function renderStudyCard(s){const n=state.surveys.filter(r=>r.study_id===s.id).length,arch=s.status==='archived';return `<article class="study-card mgmt-study-card ${arch?'archived':''}"><input class="form-check-input study-check mgmt-study-check" type="checkbox" value="${s.id}" ${mgmt.selectedStudies.has(s.id)?'checked':''}><span class="eyebrow">${esc(METHODS[s.sampling_method]||s.sampling_method)}</span><h3>${esc(s.name)}</h3><p class="small text-secondary">${esc(s.universe_definition)}</p><div class="meta"><div><span>Entrevistas</span><b>${fmt(n)}</b></div><div><span>Objetivo</span><b>${fmt(s.target_sample_size)}</b></div><div><span>Período</span><b>${esc(s.start_date)} → ${esc(s.end_date)}</b></div><div><span>Estado</span><b><span class="status-pill ${arch?'archived':''}">${arch?'Archivado':'Activo'}</span></b></div></div><div class="mgmt-study-actions"><button class="btn btn-outline-secondary btn-sm" data-study-action="view-interviews" data-id="${s.id}">Ver entrevistas</button><button class="btn btn-outline-secondary btn-sm" data-study-action="edit" data-id="${s.id}">Editar</button><button class="btn btn-outline-secondary btn-sm" data-study-action="toggle-archive" data-id="${s.id}">${arch?'Reactivar':'Archivar'}</button><button class="btn btn-outline-secondary btn-sm" data-study-action="export" data-id="${s.id}">Descargar</button><button class="btn btn-outline-danger btn-sm" data-study-action="delete" data-id="${s.id}">Eliminar</button></div>${s.updated_at?`<small class="d-block mt-2 text-secondary">Último cambio: ${dateTime(s.updated_at)} · ${esc(memberName(s.updated_by))}</small>`:''}</article>`}
  function renderStudyManager(){$('mgmtStudiesGrid').innerHTML=allDestinationStudies().map(renderStudyCard).join('')||'<span class="empty">No hay estudios.</span>';updateStudySelectionLabel();$('mgmtStudySelectAll').checked=allDestinationStudies().length>0&&allDestinationStudies().every(s=>mgmt.selectedStudies.has(s.id))}
  function updateStudySelectionLabel(){$('mgmtStudySelection')&&($('mgmtStudySelection').textContent=`${mgmt.selectedStudies.size} seleccionado${mgmt.selectedStudies.size===1?'':'s'}`)}
  function resetStudyModalMode(){$('studyEditId')&&($('studyEditId').value='');$('studyEditReasonWrap')?.classList.add('d-none');$('studyEditReason')&&($('studyEditReason').value='');$('studyModalEyebrow')&&($('studyModalEyebrow').textContent='Nuevo estudio');$('studyModalTitle')&&($('studyModalTitle').textContent='Preparar un relevamiento');$('studySubmitBtn')&&($('studySubmitBtn').textContent='Empezar estudio')}
  function openStudyEdit(id){const s=state.studies.find(x=>x.id===id);if(!s)return;$('studyEditId').value=id;$('studyModalEyebrow').textContent='Editar estudio';$('studyModalTitle').textContent=s.name;$('studySubmitBtn').textContent='Guardar cambios';$('studyEditReasonWrap').classList.remove('d-none');$('studyEditReason').value='';setInput('studyName',s.name);setInput('studyUniverse',s.universe_definition);setInput('studyMethod',s.sampling_method);setInput('studyPopulation',s.population_size);setInput('studyConfidence',s.confidence_level);setInput('studyMargin',s.target_margin_error);setInput('studyTarget',s.target_sample_size);setInput('studyMinSubgroup',s.min_subgroup_n);setInput('studyInterceptEvery',s.intercept_every);setInput('studyStart',s.start_date);setInput('studyEnd',s.end_date);setInput('studyDesignNotes',s.design_notes);$('studyModal').classList.add('show-advanced');$('studyAdvancedToggle').textContent='Ocultar configuración avanzada';updateSampleCalc();bootstrap.Modal.getOrCreateInstance($('studyModal')).show()}
  async function saveStudyEdit(e){const id=$('studyEditId')?.value;if(!id)return;e.preventDefault();e.stopImmediatePropagation();const s=state.studies.find(x=>x.id===id);if(!s)return;const reason=$('studyEditReason').value.trim();if(!reason)return toast('Indicá el motivo del cambio.','warning');const before=jsonClone(s),payload={name:$('studyName').value.trim(),universe_definition:$('studyUniverse').value.trim(),sampling_method:$('studyMethod').value,population_size:num($('studyPopulation').value),confidence_level:Number($('studyConfidence').value),target_margin_error:Number($('studyMargin').value),target_sample_size:Number($('studyTarget').value),min_subgroup_n:Number($('studyMinSubgroup').value)||100,intercept_every:Number($('studyInterceptEvery').value)||3,design_notes:$('studyDesignNotes').value.trim()||null,start_date:$('studyStart').value,end_date:$('studyEnd').value,updated_at:new Date().toISOString(),updated_by:state.user.id,last_edit_reason:reason};if(state.mode==='demo'){Object.assign(s,payload);await recordAudit({entityType:'study',entityId:s.id,action:'update',reason,before,after:jsonClone(s),studyId:s.id});saveDemo()}else{const {data,error}=await sb.from('studies').update(payload).eq('id',id).select().single();if(error)return toast(`No se pudo guardar: ${error.message}`,'danger');Object.assign(s,data)}bootstrap.Modal.getOrCreateInstance($('studyModal')).hide();renderAll();renderManagement();toast('Estudio actualizado. El cambio quedó registrado.')}
  async function toggleStudyArchive(ids){if(!ids.length)return toast('Seleccioná al menos un estudio.','warning');const selected=state.studies.filter(s=>ids.includes(s.id)),allArchived=selected.every(s=>s.status==='archived'),next=allArchived?'active':'archived',reason=allArchived?'Reactivación del estudio':'Archivo del estudio';for(const s of selected){const payload={status:next,archived_at:next==='archived'?new Date().toISOString():null,updated_at:new Date().toISOString(),updated_by:state.user.id,last_edit_reason:reason};if(state.mode==='demo'){const before=jsonClone(s);Object.assign(s,payload);await recordAudit({entityType:'study',entityId:s.id,action:next==='archived'?'archive':'restore',reason,before,after:jsonClone(s),studyId:s.id})}else{const {data,error}=await sb.from('studies').update(payload).eq('id',s.id).select().single();if(error){toast(error.message,'danger');continue}Object.assign(s,data)}}if(state.mode==='demo')saveDemo();if(state.studies.find(s=>s.id===state.activeStudyId)?.status==='archived')state.activeStudyId=allDestinationStudies().find(s=>s.status!=='archived')?.id||null;mgmt.selectedStudies.clear();renderAll();renderManagement();toast(allArchived?'Estudio(s) reactivado(s).':'Estudio(s) archivado(s).')}
  async function exportStudies(ids){if(!ids.length)return toast('Seleccioná al menos un estudio.','warning');const data=ids.map(id=>({study:state.studies.find(s=>s.id===id),questions:state.questions.filter(q=>q.study_id===id),interviews:state.surveys.filter(r=>r.study_id===id),events:state.events.filter(r=>r.study_id===id),coverage:state.coverage.filter(c=>c.study_id===id)}));downloadBlob(new Blob([JSON.stringify({product:'Destintelligence',version:'5.8',exported_at:new Date().toISOString(),destination:activeDestination(),studies:data},null,2)],{type:'application/json'}),`destintelligence-estudios-${new Date().toISOString().slice(0,10)}.json`);await recordAudit({entityType:'backup',action:'export_studies',reason:`Exportación de ${ids.length} estudio(s)`,metadata:{ids,count:ids.length}})}

  // ---------- Eliminación segura ----------
  function openDelete(kind,ids){if(!ids?.length)return toast('No hay elementos seleccionados.','warning');mgmt.deleteIds=[...ids];$('dangerDeleteKind').value=kind;$('dangerDeleteReason').value='';$('dangerDeletePhrase').value='';$('dangerDeleteConfirmBtn').disabled=true;const noun={interviews:'entrevista(s)',studies:'estudio(s)',question:'pregunta'}[kind]||'elemento(s)';$('dangerDeleteTitle').textContent=`Eliminar ${noun} definitivamente`;$('dangerDeleteText').innerHTML=`Vas a eliminar <span class="danger-count">${ids.length}</span> ${noun}. Esta acción es irreversible. Antes de continuar conviene descargar un backup.`;bootstrap.Modal.getOrCreateInstance($('dangerDeleteModal')).show()}
  async function confirmDelete(){const kind=$('dangerDeleteKind').value,reason=$('dangerDeleteReason').value.trim(),phrase=$('dangerDeletePhrase').value.trim();if(!reason)return toast('Indicá el motivo de la eliminación.','warning');if(phrase!=='ELIMINAR')return toast('Escribí ELIMINAR exactamente.','warning');$('dangerDeleteConfirmBtn').disabled=true;$('dangerDeleteConfirmBtn').textContent='Eliminando…';try{if(kind==='interviews'){if(state.mode==='demo'){const ids=new Set(mgmt.deleteIds);state.surveys=state.surveys.filter(r=>!ids.has(r.id));await recordAudit({entityType:'interview',action:'delete_bulk',reason,metadata:{ids:mgmt.deleteIds,count:mgmt.deleteIds.length}})}else{const {data,error}=await sb.rpc('hard_delete_interviews',{p_ids:mgmt.deleteIds,p_reason:reason,p_confirmation:'ELIMINAR'});if(error)throw error}mgmt.deleteIds.forEach(id=>mgmt.selectedInterviews.delete(id));const ids=new Set(mgmt.deleteIds);state.surveys=state.surveys.filter(r=>!ids.has(r.id))}else if(kind==='studies'){if(state.mode==='demo'){const ids=new Set(mgmt.deleteIds);state.surveys=state.surveys.filter(r=>!ids.has(r.study_id));state.questions=state.questions.filter(r=>!ids.has(r.study_id));state.events=state.events.filter(r=>!ids.has(r.study_id));state.coverage=state.coverage.filter(r=>!ids.has(r.study_id));state.studies=state.studies.filter(r=>!ids.has(r.id));await recordAudit({entityType:'study',action:'delete_bulk',reason,metadata:{ids:mgmt.deleteIds,count:mgmt.deleteIds.length}})}else{const {error}=await sb.rpc('hard_delete_studies',{p_ids:mgmt.deleteIds,p_reason:reason,p_confirmation:'ELIMINAR'});if(error)throw error;const ids=new Set(mgmt.deleteIds);state.surveys=state.surveys.filter(r=>!ids.has(r.study_id));state.questions=state.questions.filter(r=>!ids.has(r.study_id));state.events=state.events.filter(r=>!ids.has(r.study_id));state.coverage=state.coverage.filter(r=>!ids.has(r.study_id));state.studies=state.studies.filter(r=>!ids.has(r.id))}mgmt.selectedStudies.clear();if(!state.studies.some(s=>s.id===state.activeStudyId))state.activeStudyId=allDestinationStudies().find(s=>s.status!=='archived')?.id||allDestinationStudies()[0]?.id||null}else if(kind==='question'){const id=mgmt.deleteIds[0];if(state.mode==='demo'){const q=state.questions.find(x=>x.id===id);state.questions=state.questions.filter(x=>x.id!==id);await recordAudit({entityType:'question',entityId:id,action:'delete',reason,before:q,studyId:q?.study_id});saveDemo()}else{const {error}=await sb.rpc('hard_delete_question',{p_id:id,p_reason:reason,p_confirmation:'ELIMINAR'});if(error)throw error;state.questions=state.questions.filter(x=>x.id!==id)}renderQuestions();renderDemand()}if(state.mode==='demo')saveDemo();bootstrap.Modal.getOrCreateInstance($('dangerDeleteModal')).hide();mgmt.auditLoaded=false;renderAll();renderManagement();toast('Eliminación completada y registrada.')}catch(err){toast(`No se pudo eliminar: ${err.message||err}`,'danger')}finally{$('dangerDeleteConfirmBtn').textContent='Eliminar definitivamente';$('dangerDeleteConfirmBtn').disabled=false}}

  // ---------- Historial ----------
  const ACTION_LABELS={insert:'Creó',update:'Editó',delete:'Eliminó',delete_bulk:'Eliminó definitivamente',archive:'Archivó',restore:'Reactivó',export_csv:'Exportó CSV',export_xlsx:'Exportó Excel',export_pdf:'Exportó PDF',export_studies:'Exportó estudios',backup:'Descargó backup',user_invite:'Agregó usuario',user_update:'Editó usuario',user_status:'Cambió estado de usuario',user_delete:'Eliminó usuario'};
  async function renderAudit(){const logs=await loadAudit();const entity=$('auditEntityFilter')?.value||'',term=($('auditSearch')?.value||'').toLowerCase().trim();const rows=logs.filter(l=>(!entity||l.entity_type===entity)&&(!term||[l.actor_email,memberName(l.actor_user_id),l.action,l.entity_type,l.reason].some(v=>String(v||'').toLowerCase().includes(term)))).slice(0,500);$('auditRows').innerHTML=rows.map(l=>`<tr><td>${dateTime(l.created_at)}</td><td>${esc(memberName(l.actor_user_id)!=='—'?memberName(l.actor_user_id):(l.actor_email||'—'))}</td><td>${esc(ACTION_LABELS[l.action]||l.action)}</td><td>${esc(l.entity_type)}${l.entity_id?`<br><small>${esc(l.entity_id.slice(0,12))}</small>`:''}</td><td>${esc(l.reason||'—')}</td><td><button class="btn btn-outline-secondary btn-sm audit-detail-btn" data-audit-id="${l.id}">Ver cambios</button></td></tr>`).join('')||'<tr><td colspan="6" class="text-secondary">Todavía no hay movimientos para mostrar.</td></tr>'}
  function showAuditDetail(id){const l=mgmt.audit.find(x=>x.id===id);if(!l)return;const w=window.open('','_blank','width=900,height=720');w.document.write(`<html><head><title>Historial · Destintelligence</title><style>body{font-family:Arial;padding:24px;color:#17231f}pre{white-space:pre-wrap;background:#f5f7f6;padding:14px;border-radius:8px}h2{margin-bottom:4px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}</style></head><body><h2>Movimiento registrado</h2><p>${esc(dateTime(l.created_at))} · ${esc(memberName(l.actor_user_id)||l.actor_email||'—')}</p><p><b>Acción:</b> ${esc(ACTION_LABELS[l.action]||l.action)} · <b>Elemento:</b> ${esc(l.entity_type)}</p><p><b>Motivo:</b> ${esc(l.reason||'—')}</p><div class="grid"><div><h3>Antes</h3><pre>${esc(JSON.stringify(l.before_data,null,2)||'—')}</pre></div><div><h3>Después</h3><pre>${esc(JSON.stringify(l.after_data,null,2)||'—')}</pre></div></div><h3>Metadatos</h3><pre>${esc(JSON.stringify(l.metadata,null,2)||'—')}</pre></body></html>`);w.document.close()}

  // ---------- Backup completo ----------
  async function fetchAllOrgRows(table,orgId){const out=[];for(let from=0;;from+=1000){const {data,error}=await sb.from(table).select('*').eq('organization_id',orgId).range(from,from+999);if(error)throw error;out.push(...(data||[]));if(!data||data.length<1000)break}return out}
  async function downloadFullBackup(){try{let payload;if(state.mode==='demo'){payload={organizations:[state.org],destinations:state.destinations,members:state.members,studies:state.studies,questions:state.questions,interviews:state.surveys,field_events:state.events,coverage_targets:state.coverage,branding:Object.values(state.branding),public_snapshots:state.snapshots,audit_logs:state.auditLogs||[]}}else{const orgId=state.org.id;const [studies,questions,interviews,events,coverage,members,branding,snapshots,audit]=await Promise.all(['studies','survey_questions','visitor_records','field_events','coverage_targets','organization_members','destination_branding','public_snapshots','audit_logs'].map(t=>fetchAllOrgRows(t,orgId)));payload={organizations:[state.org],destinations:state.destinations,members,studies,questions,interviews,field_events:events,coverage_targets:coverage,branding,public_snapshots:snapshots,audit_logs:audit}}const envelope={product:'Destintelligence',version:'5.8',backup_created_at:new Date().toISOString(),organization:state.org.name,data:payload};downloadBlob(new Blob([JSON.stringify(envelope,null,2)],{type:'application/json'}),`destintelligence-backup-${safeFile(state.org.name)}-${new Date().toISOString().slice(0,10)}.json`);await recordAudit({entityType:'backup',action:'backup',reason:'Backup completo descargado',metadata:{tables:Object.keys(payload),interviews:payload.interviews?.length||0,studies:payload.studies?.length||0}});toast('Backup completo descargado.')}catch(err){toast(`No se pudo crear el backup: ${err.message||err}`,'danger')}}

  // ---------- Estudio view existente: sumar gestión ----------
  const baseRenderStudies=renderStudies;
  renderStudies=function(){if(!upper())return baseRenderStudies();const mount=$('studiesGrid');if(!mount)return;mount.innerHTML=allDestinationStudies().map(renderStudyCard).join('')||'<span class="empty">No hay estudios.</span>'};

  // Preguntas personalizadas: eliminación definitiva con confirmación fuerte.
  const strongDeleteQuestion=id=>openDelete('question',[id]);
  window.deleteQuestion=strongDeleteQuestion;
  try{deleteQuestion=strongDeleteQuestion}catch{}
  const baseRenderQuestionsV58=renderQuestions;
  renderQuestions=function(){baseRenderQuestionsV58();const qs=allStudyQuestions();qsa('#questionsList .question-card').forEach((card,i)=>{const q=qs[i];if(!q||card.querySelector('[data-v58-delete-question]'))return;const actions=card.querySelector('.question-actions');if(!actions)return;const b=document.createElement('button');b.type='button';b.className='btn btn-outline-danger btn-sm';b.dataset.v58DeleteQuestion='1';b.textContent='Eliminar';b.addEventListener('click',()=>openDelete('question',[q.id]));actions.appendChild(b)})};

  // ---------- Eventos ----------
  function bindManagement(){
    qsa('[data-mgmt-tab]').forEach(b=>b.addEventListener('click',()=>showMgmtTab(b.dataset.mgmtTab)));
    $('mgmtRefreshBtn')?.addEventListener('click',async()=>{await refreshManagementData();if(upper())await loadAudit(true);renderAll();renderManagement();toast('Información actualizada.')});
    $('mgmtBackupTopBtn')?.addEventListener('click',downloadFullBackup);$('downloadFullBackupBtn')?.addEventListener('click',downloadFullBackup);$('goInterviewsBtn')?.addEventListener('click',()=>showMgmtTab('interviews'));
    $('mgmtInterviewStudy')?.addEventListener('change',()=>{mgmt.page=1;renderInterviewManager()});$('mgmtInterviewSearch')?.addEventListener('input',()=>{mgmt.page=1;renderInterviewManager()});$('mgmtInterviewLimit')?.addEventListener('change',()=>{mgmt.page=1;renderInterviewManager()});
    $('mgmtInterviewSelectAll')?.addEventListener('change',e=>toggleVisibleInterviewSelection(e.target.checked));$('mgmtSelectAllResultsBtn')?.addEventListener('click',selectAllInterviewResults);
    $('mgmtInterviewRows')?.addEventListener('change',e=>{if(!e.target.classList.contains('mgmt-interview-check'))return;e.target.checked?mgmt.selectedInterviews.add(e.target.value):mgmt.selectedInterviews.delete(e.target.value);updateInterviewSelectionLabel()});
    $('mgmtInterviewRows')?.addEventListener('click',e=>{const b=e.target.closest('[data-interview-action]');if(!b)return;b.dataset.interviewAction==='view'?openInterviewDetail(b.dataset.id):openInterviewEdit(b.dataset.id)});
    $('mgmtPrevPage')?.addEventListener('click',()=>{mgmt.page=Math.max(1,mgmt.page-1);renderInterviewManager()});$('mgmtNextPage')?.addEventListener('click',()=>{mgmt.page++;renderInterviewManager()});
    $('mgmtCsvBtn')?.addEventListener('click',exportSelectedCsv);$('mgmtExcelBtn')?.addEventListener('click',exportSelectedExcel);$('mgmtPdfBtn')?.addEventListener('click',()=>exportSelectedPdf());$('mgmtDeleteInterviewsBtn')?.addEventListener('click',()=>openDelete('interviews',[...mgmt.selectedInterviews]));
    $('detailEditBtn')?.addEventListener('click',()=>{const id=mgmt.currentDetailId,modal=$('interviewDetailModal'),inst=bootstrap.Modal.getOrCreateInstance(modal);modal.addEventListener('hidden.bs.modal',()=>openInterviewEdit(id),{once:true});inst.hide()});$('detailPdfBtn')?.addEventListener('click',()=>{const r=state.surveys.find(x=>x.id===mgmt.currentDetailId);if(r)exportSelectedPdf([r])});
    $('surveyForm')?.addEventListener('submit',saveInterviewCorrection,true);$('surveyModal')?.addEventListener('hidden.bs.modal',resetInterviewEdit);
    $('studyForm')?.addEventListener('submit',saveStudyEdit,true);$('studyModal')?.addEventListener('hidden.bs.modal',resetStudyModalMode);
    $('mgmtStudySelectAll')?.addEventListener('change',e=>{allDestinationStudies().forEach(s=>e.target.checked?mgmt.selectedStudies.add(s.id):mgmt.selectedStudies.delete(s.id));renderStudyManager()});
    $('mgmtStudiesGrid')?.addEventListener('change',e=>{if(!e.target.classList.contains('mgmt-study-check'))return;e.target.checked?mgmt.selectedStudies.add(e.target.value):mgmt.selectedStudies.delete(e.target.value);updateStudySelectionLabel()});
    const studyAction=async e=>{const b=e.target.closest('[data-study-action]');if(!b)return;const id=b.dataset.id,a=b.dataset.studyAction;if(a==='view-interviews'){showMgmtTab('interviews');$('mgmtInterviewStudy').value=id;mgmt.page=1;renderInterviewManager()}if(a==='edit')openStudyEdit(id);if(a==='toggle-archive')await toggleStudyArchive([id]);if(a==='export')await exportStudies([id]);if(a==='delete')openDelete('studies',[id])};$('mgmtStudiesGrid')?.addEventListener('click',studyAction);$('studiesGrid')?.addEventListener('click',studyAction);
    $('mgmtArchiveStudiesBtn')?.addEventListener('click',()=>toggleStudyArchive([...mgmt.selectedStudies]));$('mgmtExportStudiesBtn')?.addEventListener('click',()=>exportStudies([...mgmt.selectedStudies]));$('mgmtDeleteStudiesBtn')?.addEventListener('click',()=>openDelete('studies',[...mgmt.selectedStudies]));
    $('dangerDeletePhrase')?.addEventListener('input',e=>{$('dangerDeleteConfirmBtn').disabled=e.target.value.trim()!=='ELIMINAR'});$('dangerDeleteConfirmBtn')?.addEventListener('click',confirmDelete);
    $('auditReloadBtn')?.addEventListener('click',async()=>{await loadAudit(true);renderAudit()});$('auditEntityFilter')?.addEventListener('change',renderAudit);$('auditSearch')?.addEventListener('input',renderAudit);$('auditRows')?.addEventListener('click',e=>{const b=e.target.closest('[data-audit-id]');if(b)showAuditDetail(b.dataset.auditId)});
  }

  bindManagement();
  // Aplicar permisos nuevamente, porque esta capa agrega una vista nueva después del init base.
  if(state.org){applyRoleAccess();renderManagement()}
})();
